// Regenerates vectors-v1.json: envelopes sealed by the TypeScript sealer
// with the TEST ONLY wrap key. The Rust crate (services/crates/kubcode-envelope)
// must open every "valid" vector and reject every "tampered" one, which pins
// the cross-language format. Run: npx tsx tests/fixtures/envelope/generate-vectors.ts
import { writeFileSync } from "node:fs";
import path from "node:path";
import { sealSecret, secretAad, type SecretContext } from "../../../lib/keys/envelope";
import { FIXTURE_DIR, TEST_PUBLIC_KEY } from "./open";

const key = { slot: 1, publicKeyPem: TEST_PUBLIC_KEY };
const user = "0b6e4f3a-1c2d-4e5f-8a9b-0c1d2e3f4a5b";

const cases: { name: string; ctx: SecretContext; plaintext: string }[] = [
  {
    name: "user secret, ascii",
    ctx: { table: "user_secrets", rowId: "6f1c2a8e-4b9d-4e3a-9c1f-2d7e8a9b0c11", userId: user, kind: "elevenlabs_api_key", version: 1 },
    plaintext: "sk_fixture_value_1234",
  },
  {
    name: "user secret, json payload, version 3",
    ctx: { table: "user_secrets", rowId: "9a8b7c6d-5e4f-4a3b-8c2d-1e0f9a8b7c6d", userId: user, kind: "youtube_oauth_client", version: 3 },
    plaintext: JSON.stringify({ client_secret: "GOCSPX-fixture-not-real" }),
  },
  {
    name: "oauth connection, utf-8",
    ctx: { table: "oauth_connections", rowId: "11111111-2222-4333-8444-555555555555", userId: user, kind: "instagram", version: 1 },
    plaintext: "โทเคนทดสอบ-fixture",
  },
];

const valid = cases.map((c) => ({
  ...c,
  aad: secretAad(c.ctx).toString("utf8"),
  envelopeHex: sealSecret(c.ctx, c.plaintext, key).toString("hex"),
}));

const base = valid[0];
const flip = (hex: string, byteIndex: number) => {
  const b = Buffer.from(hex, "hex");
  b[byteIndex] ^= 0x01;
  return b.toString("hex");
};
const tampered = [
  { name: "other user", ctx: { ...base.ctx, userId: "1b6e4f3a-1c2d-4e5f-8a9b-0c1d2e3f4a5b" }, envelopeHex: base.envelopeHex },
  { name: "other version", ctx: { ...base.ctx, version: 2 }, envelopeHex: base.envelopeHex },
  { name: "bad magic", ctx: base.ctx, envelopeHex: flip(base.envelopeHex, 0) },
  { name: "unknown slot", ctx: base.ctx, envelopeHex: flip(base.envelopeHex, 4) },
  { name: "flipped ciphertext byte", ctx: base.ctx, envelopeHex: flip(base.envelopeHex, Buffer.from(base.envelopeHex, "hex").length - 20) },
  { name: "flipped tag byte", ctx: base.ctx, envelopeHex: flip(base.envelopeHex, Buffer.from(base.envelopeHex, "hex").length - 1) },
  { name: "truncated", ctx: base.ctx, envelopeHex: base.envelopeHex.slice(0, 200) },
];

writeFileSync(
  path.join(FIXTURE_DIR, "vectors-v1.json"),
  JSON.stringify({ note: "TEST ONLY key; generated by generate-vectors.ts", slot: 1, valid, tampered }, null, 2) + "\n",
);
console.log(`wrote ${valid.length} valid + ${tampered.length} tampered vectors`);
